    <svg width={small ? 21 : 28} height={small ? 21 : 28} viewBox=\"0 0 28 28\" fill=\"none\" aria-hidden=\"true\">
      <rect x=\"4\" y=\"5\" width=\"20\" height=\"18\" rx=\"4\" stroke=\"currentColor\" strokeWidth=\"1.7\" />
