      <circle cx=\"8\" cy=\"8\" r=\".85\" fill=\"currentColor\" />
      <circle cx=\"11\" cy=\"8\" r=\".85\" fill=\"currentColor\" />
      {"'!small && <path d="m11 17 2 2 4-4" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" />}
    </svg>
  );
}

function CheckIcon() {
