    setOpen(false);
    setResult(value);
  }

  return (
    <div className=\"app\">
      <header className=\"site-header\">
        <div className=\"brand\"><span className=\"brand-mark\"><WindowIcon small /></span><span>ясно<span className=\"brand-dot\">.</span></span></div>
